const fs = require('node:fs');
const path = require('node:path');
const { Given, When, Then } = require('@cucumber/cucumber');

const ROOT = path.resolve(__dirname, '..', '..');
const STORAGE_KEY = 'todos-vanilla';
const FILTER_KEY = 'todos-vanilla-filter';

// --- DOM helpers ---------------------------------------------------------

function doc(world) {
  return world.document;
}

function allItems(document) {
  return Array.from(document.querySelectorAll('.todo-list .todo'));
}

function itemByTitle(document, title) {
  return allItems(document).find((li) => {
    const label = li.querySelector('.view label');
    return label && label.textContent.trim() === title;
  });
}

function visibleItems(document) {
  return allItems(document).filter((li) => !li.hidden);
}

function filterLink(document, name) {
  return Array.from(document.querySelectorAll('.filters a')).find(
    (a) => a.textContent.trim() === name,
  );
}

// --- Background / fixtures ----------------------------------------------

Given('the app has loaded with an empty todo list', function () {
  this.window.localStorage.removeItem(STORAGE_KEY);
  this.window.localStorage.removeItem(FILTER_KEY);
  this.reloadApp();
});

Given('the todo list contains the items:', function (dataTable) {
  const rows = dataTable.hashes();
  const items = rows.map((r, i) => ({
    id: String(i + 1),
    title: r.title,
    completed: r.completed === 'true',
  }));
  this.window.localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
  this.reloadApp();
});

// --- Creating -----------------------------------------------------------

When('I enter {string} into the new todo input and press Enter', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

Then('the todo list contains {int} items', function (n) {
  const got = allItems(this.document).length;
  if (got !== n) throw new Error(`expected ${n} items, found ${got}`);
});

Then('the item at position {int} has the title {string}', function (pos, title) {
  const items = allItems(this.document);
  const li = items[pos - 1];
  if (!li) throw new Error(`no item at position ${pos} (have ${items.length})`);
  const got = li.querySelector('.view label').textContent.trim();
  if (got !== title) throw new Error(`item at position ${pos} is "${got}", expected "${title}"`);
});

Then('the item at position {int} is not completed', function (pos) {
  const li = allItems(this.document)[pos - 1];
  if (!li) throw new Error(`no item at position ${pos}`);
  if (li.classList.contains('completed')) throw new Error(`item at position ${pos} is completed`);
});

Then('the new todo input is empty', function () {
  const input = this.document.querySelector('.new-todo');
  if (input.value !== '') throw new Error(`new todo input is "${input.value}", expected empty`);
});

Then('the main section is visible', function () {
  if (this.document.querySelector('.main').hidden) throw new Error('main section is hidden');
});

Then('the main section is hidden', function () {
  if (!this.document.querySelector('.main').hidden) throw new Error('main section is visible');
});

Then('the footer is visible', function () {
  if (this.document.querySelector('.footer').hidden) throw new Error('footer is hidden');
});

Then('the footer is hidden', function () {
  if (!this.document.querySelector('.footer').hidden) throw new Error('footer is visible');
});

// --- Toggling / completing ---------------------------------------------

When('I toggle the checkbox of the item {string}', function (title) {
  const li = itemByTitle(this.document, title);
  if (!li) throw new Error(`no item titled "${title}"`);
  const toggle = li.querySelector('.toggle');
  toggle.checked = !toggle.checked;
  toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

Then('the item {string} is completed', function (title) {
  const li = itemByTitle(this.document, title);
  if (!li) throw new Error(`no item titled "${title}"`);
  if (!li.classList.contains('completed')) throw new Error(`item "${title}" is not completed`);
});

Then('the list item for {string} has the {string} class', function (title, klass) {
  const li = itemByTitle(this.document, title);
  if (!li) throw new Error(`no item titled "${title}"`);
  if (!li.classList.contains(klass)) throw new Error(`item "${title}" lacks class "${klass}"`);
});

Then('the list item for {string} does not have the {string} class', function (title, klass) {
  const li = itemByTitle(this.document, title);
  if (!li) throw new Error(`no item titled "${title}"`);
  if (li.classList.contains(klass)) throw new Error(`item "${title}" still has class "${klass}"`);
});

When('I toggle the mark-all checkbox', function () {
  const toggleAll = this.document.querySelector('.toggle-all');
  toggleAll.checked = !toggleAll.checked;
  toggleAll.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

Then('every item is completed', function () {
  const items = allItems(this.document);
  if (items.length === 0) throw new Error('no items to check');
  for (const li of items) {
    if (!li.classList.contains('completed')) throw new Error(`item "${li.querySelector('.view label').textContent.trim()}" is not completed`);
  }
});

Then('the mark-all checkbox is checked', function () {
  if (!this.document.querySelector('.toggle-all').checked) throw new Error('mark-all checkbox is not checked');
});

Then('the mark-all checkbox is not checked', function () {
  if (this.document.querySelector('.toggle-all').checked) throw new Error('mark-all checkbox is checked');
});

// --- Counter ------------------------------------------------------------

Then('the todo count is {int}', function (n) {
  const strong = this.document.querySelector('.todo-count strong');
  if (!strong) throw new Error('no todo-count strong element');
  if (strong.textContent.trim() !== String(n)) throw new Error(`count is "${strong.textContent.trim()}", expected ${n}`);
});

Then('the todo count reads {string}', function (text) {
  const count = this.document.querySelector('.todo-count');
  const got = count.textContent.replace(/\s+/g, ' ').trim();
  if (got !== text) throw new Error(`count reads "${got}", expected "${text}"`);
});

// --- Clear completed / destroy -----------------------------------------

When('I click the clear-completed button', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (!btn) throw new Error('no clear-completed button');
  btn.click();
});

Then('the clear-completed button is hidden', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (!btn) throw new Error('no clear-completed button');
  if (!btn.hidden) throw new Error('clear-completed button is visible');
});

When('I click the destroy button for the item {string}', function (title) {
  const li = itemByTitle(this.document, title);
  if (!li) throw new Error(`no item titled "${title}"`);
  const btn = li.querySelector('.destroy');
  if (!btn) throw new Error(`no destroy button for "${title}"`);
  btn.click();
});

Then('the item {string} is present', function (title) {
  if (!itemByTitle(this.document, title)) throw new Error(`item "${title}" is absent`);
});

Then('the item {string} is absent', function (title) {
  if (itemByTitle(this.document, title)) throw new Error(`item "${title}" is present`);
});

// --- Editing ------------------------------------------------------------

When('I double-click the label of the item {string}', function (title) {
  const li = itemByTitle(this.document, title);
  if (!li) throw new Error(`no item titled "${title}"`);
  const label = li.querySelector('.view label');
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

Then('the edit input for {string} is focused', function (title) {
  const li = itemByTitle(this.document, title);
  if (!li) throw new Error(`no item titled "${title}"`);
  const edit = li.querySelector('.edit');
  if (this.document.activeElement !== edit) throw new Error(`edit input for "${title}" is not focused`);
});

When('I set the edit input to {string} and press Enter', function (text) {
  const edit = this.document.activeElement;
  if (!edit || !edit.classList.contains('edit')) throw new Error('no edit input is active');
  edit.value = text;
  edit.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When('I set the edit input to {string} and blur it', function (text) {
  const edit = this.document.activeElement;
  if (!edit || !edit.classList.contains('edit')) throw new Error('no edit input is active');
  edit.value = text;
  edit.dispatchEvent(new this.window.Event('blur'));
});

When('I set the edit input to {string}', function (text) {
  const edit = this.document.activeElement;
  if (!edit || !edit.classList.contains('edit')) throw new Error('no edit input is active');
  edit.value = text;
});

When('I press Escape in the edit input', function () {
  const edit = this.document.activeElement;
  if (!edit || !edit.classList.contains('edit')) throw new Error('no edit input is active');
  edit.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true }));
});

// --- Routing ------------------------------------------------------------

When('I navigate to {string}', function (hash) {
  this.navigate(hash);
});

Then('the visible todo list contains {int} items', function (n) {
  const got = visibleItems(this.document).length;
  if (got !== n) throw new Error(`expected ${n} visible items, found ${got}`);
});

Then('the item {string} is not visible', function (title) {
  const li = itemByTitle(this.document, title);
  if (!li) throw new Error(`no item titled "${title}"`);
  if (!li.hidden) throw new Error(`item "${title}" is visible`);
});

Then('the item {string} is visible', function (title) {
  const li = itemByTitle(this.document, title);
  if (!li) throw new Error(`no item titled "${title}"`);
  if (li.hidden) throw new Error(`item "${title}" is hidden`);
});

Then('the filter link {string} has the {string} class', function (name, klass) {
  const link = filterLink(this.document, name);
  if (!link) throw new Error(`no filter link "${name}"`);
  if (!link.classList.contains(klass)) throw new Error(`filter link "${name}" lacks class "${klass}"`);
});

Then('the filter link {string} does not have the {string} class', function (name, klass) {
  const link = filterLink(this.document, name);
  if (!link) throw new Error(`no filter link "${name}"`);
  if (link.classList.contains(klass)) throw new Error(`filter link "${name}" still has class "${klass}"`);
});

When('I reload the app', function () {
  this.reloadApp();
});

// --- Persistence --------------------------------------------------------

Then('the localStorage record {string} is a JSON array', function (key) {
  const raw = this.window.localStorage.getItem(key);
