/*
 * TodoMVC — vanilla JS implementation.
 *
 * Drives the markup in index.html. State lives in localStorage under
 * `todos-vanilla`; the active filter is persisted under `todos-vanilla-filter`
 * so it survives a reload (required by the filter-route scenarios).
 */
(function () {
  'use strict';

  var STORAGE_KEY = 'todos-vanilla';
  var FILTER_KEY = 'todos-vanilla-filter';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  var app = {
    todos: [],
    filter: 'all',
  };

  var newTodoInput;
  var main;
  var footer;
  var list;
  var toggleAll;
  var clearCompleted;
  var countEl;
  var filterLinks;

  // @planks(
  //   "the app has loaded with an empty todo list",
  //   "the todo list contains the items:"
  // )
  function load() {
    try {
      var raw = window.localStorage.getItem(STORAGE_KEY);
      app.todos = raw ? JSON.parse(raw) : [];
    } catch (e) {
      app.todos = [];
    }
  }

  // @planks(
  //   "I enter {string} into the new todo input and press Enter",
  //   "the todo list contains the items:",
  //   "I toggle the checkbox of the item {string}",
  //   "I toggle the mark-all checkbox",
  //   "I click the destroy button for the item {string}",
  //   "I set the edit input to {string} and press Enter",
  //   "I set the edit input to {string} and blur it",
  //   "I click the clear-completed button",
  //   "the app persists the todos"
  // )
  function save() {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(app.todos));
  }

  function uid() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
  }

  function findById(id) {
    for (var i = 0; i < app.todos.length; i++) {
      if (String(app.todos[i].id) === String(id)) return app.todos[i];
    }
    return null;
  }

  function activeCount() {
    return app.todos.filter(function (t) { return !t.completed; }).length;
  }

  // @planks(
  //   "the visible todo list contains {int} items",
  //   "I navigate to {string}",
  //   "the item {string} is not visible",
  //   "the item {string} is visible"
  // )
  function currentFilter() {
    var persisted = window.localStorage.getItem(FILTER_KEY);
    if (persisted === '#/active') return 'active';
    if (persisted === '#/completed') return 'completed';
    var hash = window.location.hash;
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  // @planks(
  //   "the todo list contains {int} items",
  //   "the item at position {int} has the title {string}",
  //   "the item at position {int} is not completed",
  //   "the item {string} is completed",
  //   "the list item for {string} has the {string} class",
  //   "the list item for {string} does not have the {string} class",
  //   "every item is completed",
  //   "the mark-all checkbox is checked",
  //   "the mark-all checkbox is not checked",
  //   "the todo count is {int}",
  //   "the todo count reads {string}",
  //   "the clear-completed button is hidden",
  //   "the item {string} is present",
  //   "the item {string} is absent",
  //   "the main section is visible",
  //   "the main section is hidden",
  //   "the footer is visible",
  //   "the footer is hidden",
  //   "the filter link {string} has the {string} class",
  //   "the filter link {string} does not have the {string} class"
  // )
  function render() {
    list.innerHTML = '';
    app.todos.forEach(function (todo) {
      var li = document.createElement('li');
      li.className = 'todo' + (todo.completed ? ' completed' : '');
      li.dataset.id = String(todo.id);

      var view = document.createElement('div');
      view.className = 'view';

      var toggle = document.createElement('input');
      toggle.type = 'checkbox';
      toggle.className = 'toggle';
      toggle.checked = !!todo.completed;

      var label = document.createElement('label');
      label.textContent = todo.title;

      var destroy = document.createElement('button');
      destroy.className = 'destroy';

      view.appendChild(toggle);
      view.appendChild(label);
      view.appendChild(destroy);

      var edit = document.createElement('input');
      edit.className = 'edit';
      edit.value = todo.title;

      li.appendChild(view);
      li.appendChild(edit);
      list.appendChild(li);
    });

    var active = activeCount();
    var completed = app.todos.length - active;
    var hasTodos = app.todos.length > 0;

    main.hidden = !hasTodos;
    footer.hidden = !hasTodos;

    countEl.innerHTML =
      '<strong>' + active + '</strong> ' + (active === 1 ? 'item' : 'items') + ' left';

    toggleAll.checked = hasTodos && active === 0;
    clearCompleted.hidden = completed === 0;

    Array.prototype.forEach.call(list.children, function (li) {
      var todo = findById(li.dataset.id);
      if (!todo) return;
      var show =
        app.filter === 'all' ||
        (app.filter === 'active' && !todo.completed) ||
        (app.filter === 'completed' && todo.completed);
      li.hidden = !show;
    });

    Array.prototype.forEach.call(filterLinks, function (a) {
      var href = a.getAttribute('href');
      var match =
        (href === '#/' && app.filter === 'all') ||
        (href === '#/active' && app.filter === 'active') ||
        (href === '#/completed' && app.filter === 'completed');
      if (match) a.classList.add('selected');
      else a.classList.remove('selected');
    });

    save();
  }

  // @planks("I enter {string} into the new todo input and press Enter")
  function onNewTodoKey(e) {
    if (e.key === 'Enter' || e.keyCode === ENTER_KEY) {
      var title = newTodoInput.value.trim();
      if (title !== '') {
        app.todos.push({ id: uid(), title: title, completed: false });
        newTodoInput.value = '';
        save();
        render();
      }
    }
  }

  // @planks("I toggle the checkbox of the item {string}")
  function onListChange(e) {
    if (!e.target.classList.contains('toggle')) return;
    var li = e.target.closest('.todo');
    var todo = findById(li.dataset.id);
    if (!todo) return;
    todo.completed = e.target.checked;
    save();
    render();
  }

  // @planks("I toggle the mark-all checkbox")
  function onToggleAll() {
    var allCompleted = toggleAll.checked;
    app.todos.forEach(function (t) { t.completed = allCompleted; });
    save();
    render();
  }

  // @planks("I click the destroy button for the item {string}")
  function onListClick(e) {
    var destroy = e.target.closest('.destroy');
    if (!destroy) return;
    var li = destroy.closest('.todo');
    var todo = findById(li.dataset.id);
    if (!todo) return;
    app.todos = app.todos.filter(function (t) { return String(t.id) !== String(todo.id); });
    save();
    render();
  }

  // @planks("I double-click the label of the item {string}")
  function onListDblClick(e) {
    var label = e.target.closest('label');
    if (!label) return;
    var li = label.closest('.todo');
    var todo = findById(li.dataset.id);
    if (!todo) return;
    li.classList.add('editing');
    var edit = li.querySelector('.edit');
    edit.value = todo.title;
    edit.focus();
  }

  function commitEdit(edit) {
    var li = edit.closest('.todo');
    var todo = findById(li.dataset.id);
    if (!todo) return;
    var title = edit.value.trim();
    if (title === '') {
      app.todos = app.todos.filter(function (t) { return String(t.id) !== String(todo.id); });
    } else {
      todo.title = title;
    }
    save();
    render();
  }

  function cancelEdit(edit) {
    var li = edit.closest('.todo');
    var todo = findById(li.dataset.id);
    if (todo) edit.value = todo.title;
    li.classList.remove('editing');
    edit.blur();
  }

  // @planks(
  //   "I set the edit input to {string} and press Enter",
  //   "I set the edit input to {string} and blur it",
  //   "I press Escape in the edit input"
  // )
  function onListKey(e) {
    if (!e.target.classList.contains('edit')) return;
    if (e.key === 'Enter' || e.keyCode === ENTER_KEY) commitEdit(e.target);
    else if (e.key === 'Escape' || e.keyCode === ESCAPE_KEY) cancelEdit(e.target);
  }

  // @planks("I set the edit input to {string} and blur it")
  function onListBlur(e) {
    if (!e.target.classList.contains('edit')) return;
    var li = e.target.closest('.todo');
    if (li && li.classList.contains('editing')) commitEdit(e.target);
  }

  // @planks("I navigate to {string}")
  function onRoute() {
    app.filter = currentFilter();
    if (window.location.hash === '#/active' || window.location.hash === '#/completed') {
      window.localStorage.setItem(FILTER_KEY, window.location.hash);
    }
    render();
  }

  // @planks("I click the clear-completed button")
  function onClearCompleted() {
    app.todos = app.todos.filter(function (t) { return !t.completed; });
    save();
    render();
  }

  function init() {
    newTodoInput = document.querySelector('.new-todo');
    main = document.querySelector('.main');
    footer = document.querySelector('.footer');
    list = document.querySelector('.todo-list');
    toggleAll = document.querySelector('.toggle-all');
    clearCompleted = document.querySelector('.clear-completed');
    countEl = document.querySelector('.todo-count');
    filterLinks = document.querySelectorAll('.filters a');

    load();
    app.filter = currentFilter();

    window.addEventListener('hashchange', onRoute);
    newTodoInput.addEventListener('keydown', onNewTodoKey);
    toggleAll.addEventListener('change', onToggleAll);
    list.addEventListener('change', onListChange);
    list.addEventListener('click', onListClick);
    list.addEventListener('dblclick', onListDblClick);
    list.addEventListener('keydown', onListKey);
    list.addEventListener('blur', onListBlur, true);
    clearCompleted.addEventListener('click', onClearCompleted);

    render();

    // Expose a narrow persistence hook for the schema-conformance step.
    window.todoApp = { save: save };
  }

  init();
})();

